#!/usr/bin/env python3
"""gen_pki.py — the sc22 test PKI, built from scratch and pinned.

Authoring provenance for `vendor/vectors/pki/*.hex` (the sc17/sc20
extractor+reference discipline, inverted: the certificates are AUTHORED
by this from-scratch reference — RFC 8032 Ed25519 + a hand-built X.690
DER encoder, no library — and CROSS-CHECKED with the independent tool,
openssl 3.6.3: `openssl verify` validates the chain including the
Ed25519 signatures, and `openssl x509 -text` re-parses every field, so
a builder bug and a std.x.tls.cert parser bug cannot agree by
construction). Keys are DETERMINISTIC (seeds are SHA-512/SHA-256 of
fixed strings, below), so re-running this script reproduces every
Ed25519 certificate byte-for-byte. The two non-Ed25519 certificates
(rsa.hex, ecdsa.hex) are generated by openssl (RSA keygen is not
deterministic; the vendored bytes are the pin — see README.md).

This script is PROVENANCE, not rig machinery: CI never runs it (no
build scripts, D33); the committed .hex files are the vendored corpus,
exactly as the RFC texts are. Re-run by hand only, with the output
diffed deliberately.

Certificates emitted (all Ed25519 unless said otherwise):
  root.hex          self-signed CA (v3, BC critical CA:TRUE pathLen 1,
                    KU critical keyCertSign|cRLSign, an unknown
                    NON-critical extension carried-and-ignored)
  leaf.hex          signed by root (v3, serial 0x1337, BC non-critical
                    CA:FALSE (DER: empty SEQUENCE), KU digitalSignature,
                    SAN dns wolf.example + www.wolf.example, plus an
                    unknown NON-critical extension)
  leaf2_nonca.hex   signed by the LEAF's key (issuer = leaf's subject) —
                    the not-a-CA-signing negative
  critext.hex       signed by root, carries a CRITICAL unknown extension
                    (1.3.6.1.4.1.55555.1) — the unknown-critical negative
  other_root.hex    a second self-signed CA — the wrong-trust-anchor
                    (issuer_mismatch) negative
  bad_*.hex         the malformed-encoding conformance set (each one
                    grammar-level; the X.690/RFC 5280 clause each
                    violates is in VARIANTS below and in the test file)

Every hex file is the DER of one certificate, lowercase hex, one line.
"""

import hashlib
import os

OUT = os.path.dirname(os.path.abspath(__file__))

# ----------------------------------------------------------------------
# Ed25519 from RFC 8032 (reference-style, from scratch).
# ----------------------------------------------------------------------

P = 2**255 - 19
L = 2**252 + 27742317777372353535851937790883648493
D = -121665 * pow(121666, P - 2, P) % P
BX = 15112221349535400772501151409588531511454012693041857206046113283949847762202
BY = 46316835694926478169428394003475163141307993866256225615783033603165251855960
B = (BX, BY, 1, BX * BY % P)


def sha512(m):
    return hashlib.sha512(m).digest()


def point_add(p, q):
    x1, y1, z1, t1 = p
    x2, y2, z2, t2 = q
    a = (y1 - x1) * (y2 - x2) % P
    b = (y1 + x1) * (y2 + x2) % P
    c = 2 * t1 * t2 * D % P
    dd = 2 * z1 * z2 % P
    e, f, g, h = b - a, dd - c, dd + c, b + a
    return (e * f % P, g * h % P, f * g % P, e * h % P)


def scalar_mult(s, p):
    q = (0, 1, 1, 0)
    while s > 0:
        if s & 1:
            q = point_add(q, p)
        p = point_add(p, p)
        s >>= 1
    return q


def point_compress(p):
    x, y, z, _ = p
    zi = pow(z, P - 2, P)
    x, y = x * zi % P, y * zi % P
    return int.to_bytes(y | ((x & 1) << 255), 32, "little")


def secret_expand(seed):
    h = sha512(seed)
    a = int.from_bytes(h[:32], "little")
    a &= (1 << 254) - 8
    a |= 1 << 254
    return a, h[32:]


def public_key(seed):
    a, _ = secret_expand(seed)
    return point_compress(scalar_mult(a, B))


def sign(seed, msg):
    a, prefix = secret_expand(seed)
    pk = point_compress(scalar_mult(a, B))
    r = int.from_bytes(sha512(prefix + msg), "little") % L
    rp = point_compress(scalar_mult(r, B))
    k = int.from_bytes(sha512(rp + pk + msg), "little") % L
    s = (r + k * a) % L
    return rp + int.to_bytes(s, 32, "little")


def point_decompress(b):
    y = int.from_bytes(b, "little")
    sign_x = y >> 255
    y &= (1 << 255) - 1
    if y >= P:
        return None
    x2 = (y * y - 1) * pow(D * y * y + 1, P - 2, P) % P
    x = pow(x2, (P + 3) // 8, P)
    if (x * x - x2) % P != 0:
        x = x * pow(2, (P - 1) // 4, P) % P
    if (x * x - x2) % P != 0:
        return None
    if x == 0 and sign_x:
        return None
    if x & 1 != sign_x:
        x = P - x
    return (x, y, 1, x * y % P)


def verify(pk, msg, sig):
    if len(sig) != 64 or len(pk) != 32:
        return False
    a = point_decompress(pk)
    if a is None:
        return False
    rp = point_decompress(sig[:32])
    if rp is None:
        return False
    s = int.from_bytes(sig[32:], "little")
    if s >= L:
        return False
    k = int.from_bytes(sha512(sig[:32] + pk + msg), "little") % L
    lhs = scalar_mult(s, B)
    rhs = point_add(rp, scalar_mult(k, a))
    lx, ly, lz, _ = lhs
    rx, ry, rz, _ = rhs
    return (lx * rz - rx * lz) % P == 0 and (ly * rz - ry * lz) % P == 0


# RFC 8032 §7.1 TEST 1 self-check: the reference must reproduce the RFC.
_sk1 = bytes.fromhex(
    "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60"
)
assert public_key(_sk1).hex() == (
    "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a"
)
assert sign(_sk1, b"").hex() == (
    "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555f"
    "b8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b"
)
assert verify(public_key(_sk1), b"", sign(_sk1, b""))

# ----------------------------------------------------------------------
# X.690 DER encoding (hand-built, minimal-form by construction).
# ----------------------------------------------------------------------


def der_len(n):
    if n < 128:
        return bytes([n])
    body = b""
    while n > 0:
        body = bytes([n % 256]) + body
        n //= 256
    return bytes([0x80 + len(body)]) + body


def tlv(tag, content):
    return bytes([tag]) + der_len(len(content)) + content


def seq(*parts):
    return tlv(0x30, b"".join(parts))


def der_set(*parts):
    # DER SET OF: elements sorted by encoding (X.690 §11.6).
    return tlv(0x31, b"".join(sorted(parts)))


def der_int(v):
    if v == 0:
        return tlv(0x02, b"\x00")
    neg = v < 0
    body = v.to_bytes((v.bit_length() + 8) // 8, "big", signed=True)
    # minimal two's-complement (int.to_bytes with signed already minimal
    # at that width; strip a redundant leading byte if any)
    while len(body) > 1 and (
        (body[0] == 0x00 and body[1] < 0x80) or (body[0] == 0xFF and body[1] >= 0x80)
    ):
        body = body[1:]
    assert neg == (body[0] >= 0x80) or not neg
    return tlv(0x02, body)


def oid(dotted):
    arcs = [int(x) for x in dotted.split(".")]
    body = bytes([arcs[0] * 40 + arcs[1]])
    for a in arcs[2:]:
        enc = bytes([a % 128])
        a //= 128
        while a > 0:
            enc = bytes([0x80 + a % 128]) + enc
            a //= 128
        body += enc
    return tlv(0x06, body)


def bitstring(payload, unused=0):
    return tlv(0x03, bytes([unused]) + payload)


def octetstring(payload):
    return tlv(0x04, payload)


def utf8(s):
    return tlv(0x0C, s.encode())


def printable(s):
    return tlv(0x13, s.encode())


def ia5(s):
    return tlv(0x16, s.encode())


def utctime(s):
    return tlv(0x17, s.encode())


def gentime(s):
    return tlv(0x18, s.encode())


def boolean(v):
    return tlv(0x01, b"\xff" if v else b"\x00")


def ctx(n, content, constructed=True):
    return tlv((0xA0 if constructed else 0x80) + n, content)


OID_ED25519 = "1.3.101.112"
OID_CN = "2.5.4.3"
OID_OU = "2.5.4.11"
OID_BC = "2.5.29.19"
OID_KU = "2.5.29.15"
OID_SAN = "2.5.29.17"
OID_SKI = "2.5.29.14"
OID_UNKNOWN_NONCRIT = "1.3.6.1.4.1.55555.2"
OID_UNKNOWN_CRIT = "1.3.6.1.4.1.55555.1"
OID_RSA_SHA256 = "1.2.840.113549.1.1.11"


def alg_ed25519():
    return seq(oid(OID_ED25519))


def dn_cn(cn, use_utf8=True):
    val = utf8(cn) if use_utf8 else printable(cn)
    return seq(der_set(seq(oid(OID_CN), val)))


def ext(oid_dotted, critical, inner_der):
    parts = [oid(oid_dotted)]
    if critical:
        parts.append(boolean(True))
    parts.append(octetstring(inner_der))
    return seq(*parts)


def ext_bc_ca(pathlen=None):
    inner = boolean(True)
    if pathlen is not None:
        inner += der_int(pathlen)
    return ext(OID_BC, True, seq(inner))


def ext_bc_leaf():
    # cA DEFAULT FALSE: DER encodes the default by ABSENCE — empty SEQ.
    return ext(OID_BC, False, seq())


def key_usage_bits(bits):
    # bits: list of named-bit indexes (0 = digitalSignature ... 6 = cRLSign)
    hi = max(bits)
    nbytes = hi // 8 + 1
    val = bytearray(nbytes)
    for b in bits:
        val[b // 8] |= 0x80 >> (b % 8)
    unused = 7 - (hi % 8)
    return bitstring(bytes(val), unused)


def ext_ku(bits, critical):
    return ext(OID_KU, critical, key_usage_bits(bits))


def ext_san(dns_names):
    return ext(OID_SAN, False, seq(*[ctx(2, n.encode(), constructed=False) for n in dns_names]))


def tbs(
    serial,
    issuer,
    not_before,
    not_after,
    subject,
    spki_pub,
    exts,
    version=2,
    alg=None,
    nb_kind=utctime,
    na_kind=utctime,
    unique_id=None,
):
    if alg is None:
        alg = alg_ed25519()
    parts = [ctx(0, der_int(version)), serial, alg, issuer]
    parts.append(seq(nb_kind(not_before), na_kind(not_after)))
    parts.append(subject)
    parts.append(seq(alg_ed25519(), bitstring(spki_pub)))
    if unique_id is not None:
        parts.append(tlv(0x81, unique_id))  # issuerUniqueID [1] IMPLICIT
    if exts is not None:
        parts.append(ctx(3, seq(*exts)))
    return seq(*parts)


def cert(tbs_der, seed, outer_alg=None, sig_unused=0):
    sig = sign(seed, tbs_der)
    if outer_alg is None:
        outer_alg = alg_ed25519()
    return seq(tbs_der, outer_alg, bitstring(sig, sig_unused))


# ----------------------------------------------------------------------
# The PKI (deterministic seeds).
# ----------------------------------------------------------------------

root_seed = hashlib.sha256(b"wolf-std sc22 pki: root seed").digest()
leaf_seed = hashlib.sha256(b"wolf-std sc22 pki: leaf seed").digest()
other_seed = hashlib.sha256(b"wolf-std sc22 pki: other root seed").digest()
rogue_seed = hashlib.sha256(b"wolf-std sc22 pki: rogue seed").digest()
crit_seed = hashlib.sha256(b"wolf-std sc22 pki: critext seed").digest()

ROOT_DN = dn_cn("wolf-std sc22 test root", use_utf8=True)
OTHER_DN = dn_cn("wolf-std sc22 other root", use_utf8=True)
LEAF_DN = dn_cn("wolf.example", use_utf8=False)
ROGUE_DN = dn_cn("rogue.wolf.example", use_utf8=False)
CRIT_DN = dn_cn("critext.wolf.example", use_utf8=False)

ROOT_NB, ROOT_NA = "250101000000Z", "351231235959Z"
LEAF_NB, LEAF_NA = "260101000000Z", "270101000000Z"

root_tbs = tbs(
    der_int(1),
    ROOT_DN,
    ROOT_NB,
    ROOT_NA,
    ROOT_DN,
    public_key(root_seed),
    [
        ext_bc_ca(pathlen=1),
        ext_ku([5, 6], True),
        ext(OID_SKI, False, octetstring(hashlib.sha256(public_key(root_seed)).digest()[:20])),
    ],
)
root = cert(root_tbs, root_seed)

leaf_exts = [
    ext_bc_leaf(),
    ext_ku([0], False),
    ext_san(["wolf.example", "www.wolf.example"]),
    ext(OID_UNKNOWN_NONCRIT, False, tlv(0x05, b"")),
]
leaf_tbs = tbs(
    der_int(0x1337),
    ROOT_DN,
    LEAF_NB,
    LEAF_NA,
    LEAF_DN,
    public_key(leaf_seed),
    leaf_exts,
)
leaf = cert(leaf_tbs, root_seed)

other_root_tbs = tbs(
    der_int(7),
    OTHER_DN,
    ROOT_NB,
    ROOT_NA,
    OTHER_DN,
    public_key(other_seed),
    [ext_bc_ca(), ext_ku([5], True)],
)
other_root = cert(other_root_tbs, other_seed)

# signed by the LEAF (a non-CA): the not_ca negative. Chain: rogue, leaf.
rogue_tbs = tbs(
    der_int(99),
    LEAF_DN,
    LEAF_NB,
    LEAF_NA,
    ROGUE_DN,
    public_key(rogue_seed),
    [ext_bc_leaf(), ext_san(["rogue.wolf.example"])],
)
rogue = cert(rogue_tbs, leaf_seed)

# signed by root, carries a CRITICAL unknown extension.
crit_tbs = tbs(
    der_int(66),
    ROOT_DN,
    LEAF_NB,
    LEAF_NA,
    CRIT_DN,
    public_key(crit_seed),
    [
        ext_bc_leaf(),
        ext_san(["critext.wolf.example"]),
        ext(OID_UNKNOWN_CRIT, True, tlv(0x05, b"")),
    ],
)
critext = cert(crit_tbs, root_seed)

# ----------------------------------------------------------------------
# The malformed-encoding conformance set. Each variant violates exactly
# one X.690/RFC 5280 clause; every one must be a clean `der` rejection.
# ----------------------------------------------------------------------


def leaf_variant(**kw):
    t = tbs(
        kw.get("serial", der_int(0x1337)),
        ROOT_DN,
        kw.get("nb", LEAF_NB),
        kw.get("na", LEAF_NA),
        kw.get("subject", LEAF_DN),
        public_key(leaf_seed),
        kw.get("exts", leaf_exts),
        version=kw.get("version", 2),
        alg=kw.get("alg", None),
        nb_kind=kw.get("nb_kind", utctime),
        na_kind=kw.get("na_kind", utctime),
        unique_id=kw.get("unique_id", None),
    )
    return cert(
        t,
        root_seed,
        outer_alg=kw.get("outer_alg", None),
        sig_unused=kw.get("sig_unused", 0),
    )


VARIANTS = {
    # RFC 5280 §4.1.2.5: dates through 2049 MUST be UTCTime.
    "bad_gentime_pre2050": leaf_variant(nb="20260101000000Z", nb_kind=gentime),
    # RFC 5280 §4.1.2.5.1: UTCTime MUST include seconds and end in Z.
    "bad_utctime_no_seconds": leaf_variant(nb="2601010000Z"),
    # UTCTime with an out-of-range month.
    "bad_time_month_13": leaf_variant(nb="261301000000Z"),
    # RFC 5280 §4.1.2.1: v2 (INTEGER 1) is not a v3 certificate.
    "bad_version_v2": leaf_variant(version=1),
    # RFC 5280 §4.1.2.2: serial MUST be positive.
    "bad_negative_serial": leaf_variant(serial=der_int(-5)),
    # X.690 §8.3.2: INTEGER must be minimally encoded (00 then < 0x80).
    "bad_nonminimal_serial": leaf_variant(serial=tlv(0x02, b"\x00\x37")),
    # X.690 §10.1: length must use the definite SHORT form when it fits
    # (long-form 0x81 for a 2-byte content is non-minimal DER).
    "bad_nonminimal_length": leaf_variant(serial=b"\x02\x81\x02\x13\x37"),
    # X.690 §11.1: BOOLEAN TRUE is 0xFF in DER (0x01 is BER, rejected).
    "bad_boolean_01": leaf_variant(
        exts=[ext(OID_BC, True, seq(tlv(0x01, b"\x01"))), ext_san(["wolf.example"])]
    ),
    # X.690 §11.5: a DEFAULT value (critical FALSE) must be ABSENT.
    "bad_critical_false_encoded": leaf_variant(
        exts=[
            ext_bc_leaf(),
            seq(oid(OID_SAN), boolean(False), octetstring(seq(ctx(2, b"wolf.example", constructed=False)))),
        ]
    ),
    # RFC 5280 §4.1.2.3: TBS `signature` must equal the outer algorithm.
    "bad_alg_mismatch": leaf_variant(outer_alg=seq(oid(OID_RSA_SHA256), tlv(0x05, b""))),
    # RFC 8410 §3: the Ed25519 AlgorithmIdentifier has NO parameters.
    "bad_ed25519_params": leaf_variant(
        alg=seq(oid(OID_ED25519), tlv(0x05, b"")),
        outer_alg=seq(oid(OID_ED25519), tlv(0x05, b"")),
    ),
    # RFC 5280 §4.1.1.3: the signature BIT STRING has 0 unused bits.
    "bad_sig_unused_bits": leaf_variant(sig_unused=1),
    # RFC 5280 §4.2: at most one instance of a particular extension.
    "bad_duplicate_ext": leaf_variant(
        exts=[ext_bc_leaf(), ext_ku([0], False), ext_ku([0], False), ext_san(["wolf.example"])]
    ),
    # RFC 5280 §4.2.1.6: a SAN extension MUST contain at least one name.
    "bad_empty_san": leaf_variant(exts=[ext_bc_leaf(), ext(OID_SAN, False, seq())]),
    # X.690 §11.6: SET OF elements are sorted by their DER encodings.
    "bad_unsorted_set": leaf_variant(
        subject=seq(
            tlv(
                0x31,
                seq(oid(OID_OU), printable("zz"))  # OU sorts after CN by encoding
                + seq(oid(OID_CN), printable("aa")),
            )
        )
    ),
    # RFC 5280 §4.1.2.8: unique identifiers MUST NOT be generated.
    "bad_unique_id": leaf_variant(unique_id=b"\x00\xaa\xbb"),
    # X.690 §8.19.2: an OID subidentifier has no 0x80 padding octet.
    "bad_oid_padded_arc": leaf_variant(
        exts=[
            ext_bc_leaf(),
            seq(tlv(0x06, b"\x55\x1d\x80\x11"), octetstring(seq(ctx(2, b"wolf.example", constructed=False)))),
        ]
    ),
    # RFC 5280 §4.2.1.9: pathLen without cA TRUE must be rejected.
    "bad_pathlen_without_ca": leaf_variant(
        exts=[ext(OID_BC, False, seq(der_int(0))), ext_san(["wolf.example"])]
    ),
}

# ----------------------------------------------------------------------
# Self-checks: the chain must verify under the reference itself.
# ----------------------------------------------------------------------

assert verify(public_key(root_seed), root_tbs, root[-64:])
assert verify(public_key(root_seed), leaf_tbs, leaf[-64:])
assert verify(public_key(leaf_seed), rogue_tbs, rogue[-64:])
assert verify(public_key(root_seed), crit_tbs, critext[-64:])

# ----------------------------------------------------------------------
# Emit.
# ----------------------------------------------------------------------

FILES = {
    "root.hex": root,
    "leaf.hex": leaf,
    "other_root.hex": other_root,
    "rogue_nonca.hex": rogue,
    "critext.hex": critext,
}
FILES.update({f"{k}.hex": v for k, v in VARIANTS.items()})

for name, der in FILES.items():
    with open(os.path.join(OUT, name), "w") as f:
        f.write(der.hex() + "\n")

# PEM copies of the Ed25519 chain pieces for the openssl cross-check.
import base64


def pem(der, label="CERTIFICATE"):
    b64 = base64.encodebytes(der).decode().replace("\n", "")
    lines = [b64[i : i + 64] for i in range(0, len(b64), 64)]
    return f"-----BEGIN {label}-----\n" + "\n".join(lines) + f"\n-----END {label}-----\n"


with open(os.path.join(OUT, "root.pem"), "w") as f:
    f.write(pem(root))
with open(os.path.join(OUT, "leaf.pem"), "w") as f:
    f.write(pem(leaf))

print("seeds:")
print("  root :", root_seed.hex())
print("  leaf :", leaf_seed.hex())
print("  other:", other_seed.hex())
print("  rogue:", rogue_seed.hex())
print("  crit :", crit_seed.hex())
print("public keys:")
print("  root :", public_key(root_seed).hex())
print("  leaf :", public_key(leaf_seed).hex())
print("sizes:", {k: len(v) for k, v in FILES.items()})
